const entrada = $input.first().json;
const politicas = entrada.politicas_extraidas || entrada;
const productos = entrada.productos || politicas.productos || [];
const regla = entrada.regla_descuento || politicas.regla_descuento || '';
const plazo = entrada.plazo_pago_max || politicas.plazo_pago_max || '';
const fuentes = entrada.fuentes_citadas || politicas.fuentes_citadas || [];
const mensaje = entrada.mensaje_cliente || entrada.mensaje_original || '';

return [{
  json: {
    productos, regla_descuento: regla, plazo_pago_max: plazo, fuentes_citadas: fuentes, mensaje_cliente: mensaje,
    politicas_extraidas: { productos, regla_descuento: regla, plazo_pago_max: plazo, fuentes_citadas: fuentes }
  }
}];

let rawText = $input.first().json.choices?.[0]?.message?.content || $input.first().json.text || "";

let cleanText = rawText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

try {
  const parsedJson = JSON.parse(cleanText);
  return [{ json: parsedJson }];
} catch (e) {
  return [{ json: { 
    error: "Formato JSON inválido devuelto por el LLM", 
    raw_output: rawText,
    fallback_action: "REQUIERE_REVISION" 
  }}];
}

